import { ScatterChartAdapter, useScatterChart } from '@dreadnought/react/unstyled';
const series=[{id:'a',label:'A',data:[{id:'one',label:'One',x:2,y:4,size:25}]}];
function Summary(){const {visible}=useScatterChart();return <p>Видимых: {visible.length}</p>;}
export function Example(){return <ScatterChartAdapter label="Данные" series={series} xDomain={[0,10]} yDomain={[0,10]}><Summary/><ScatterChartAdapter.Legend>{({defaultContent})=><span>{defaultContent}</span>}</ScatterChartAdapter.Legend><ScatterChartAdapter.Plot tooltipContent={({defaultContent})=><div>{defaultContent}</div>}>{({defaultContent})=>defaultContent}</ScatterChartAdapter.Plot><ScatterChartAdapter.Empty/><ScatterChartAdapter.Table/><ScatterChartAdapter.Pagination/></ScatterChartAdapter>;}
